import type {
  CanvasData,
  ChatAttachment,
  ChatMessage,
  ChatPart,
  Observation,
  ObservationKind,
  StudioError,
} from "../../types";
import { asStudioError } from "../../api/studioApi";
import { BffError, notFound } from "../errors";
import type { LocalStore } from "../store/types";
import { LocalDataService } from "../data/localDataService";
import { LocalMemoryService } from "../memory/localMemoryService";
import { createSseParser, type RawSseEvent } from "../../api/sse";

type Provider = "endpoint" | "deterministic";

function isEndpointConfigured(request: {
  base_url: string;
  api_key: string;
  model: string;
}): boolean {
  return Boolean(
    request.base_url &&
      request.api_key &&
      request.model &&
      request.base_url !== "http://localhost:8001/v1",
  );
}

const TOOLS = [
  {
    name: "get_canvas",
    description: "Read the current ODI canvas: jobs, steps, and outcomes.",
    parameters: { type: "object", properties: {}, required: [] },
  },
  {
    name: "create_job",
    description: "Create a new job on the canvas.",
    parameters: {
      type: "object",
      properties: {
        name: { type: "string", description: "Job name." },
        description: { type: "string", description: "Optional job description." },
      },
      required: ["name"],
    },
  },
  {
    name: "update_job",
    description: "Rename or describe an existing job.",
    parameters: {
      type: "object",
      properties: {
        job_id: { type: "string" },
        name: { type: "string" },
        description: { type: "string" },
      },
      required: ["job_id"],
    },
  },
  {
    name: "delete_job",
